exec(open('/tmp/load.py').read())
GRID=F(1,10000)
def floor_at(ts):
    for v in pol['versions']:
        if v['from']<=ts<v['to']: return F(str(v['floor']))
retids={r['run_id']:r['reason'] for r in ret}
V={**E,**{r:v for r,v in REC.items() if r in L}}
# bounds for unknown runs
B={}
for r in L:
    if r in V: continue
    s=plan[r]['suite']; lo=F(str(suites[s]['random_guess'])) if suites[s]['scoring']=='raw' else F(0); hi=F(1)
    fl=floor_at(RT[r])
    code=retids.get(r)
    if code=='RSN-04': hi=min(hi,fl-GRID)
    elif code=='RSN-11': lo=max(lo,fl)
    assert lo<=hi,(r,lo,hi)
    B[r]=(lo,hi)
byday=collections.defaultdict(list)
for r in B: byday[RT[r][:10]].append(r)
resid={}
for d,(n,s) in dig.items():
    runs=[r for r in L if RT[r][:10]==d]
    resid[d]=s-sum(V[r] for r in runs if r in V)
    lo=sum(B[r][0] for r in byday[d]); hi=sum(B[r][1] for r in byday[d])
    assert lo<=resid[d]<=hi,(d,lo,resid[d],hi)
def opt(w,sign):
    # maximize sign*sum w_i x_i ; returns sum over all unknowns of w_i x_i at optimum
    total=F(0)
    for d,runs in byday.items():
        x={r:B[r][0] for r in runs}; R=resid[d]-sum(x.values())
        for r in sorted(runs,key=lambda r:-sign*w.get(r,F(0))):
            inc=min(R,B[r][1]-B[r][0]); x[r]+=inc; R-=inc
        assert R==0
        total+=sum(w.get(r,F(0))*x[r] for r in runs)
    return total
def interval(w,const):
    return const+opt(w,-1), const+opt(w,1)
def cellruns(c): return [r for r in L if all(plan[r][k]==c[k] for k in ('suite','curriculum','retrieval','decoder'))]
def lin_mean(c):
    rs=cellruns(c); n=F(len(rs)); const=sum(V[r] for r in rs if r in V)/n
    w={r:F(1)/n for r in rs if r not in V}
    return const,w
def combine(a,b,sb):
    return a[0]+sb*b[0], {**a[1], **{r:a[1].get(r,F(0))+sb*v for r,v in b[1].items()}}
Q=json.load(open('queries.json'))
out={'cells':{},'contrasts':{},'decisions':{},'supports':{},'mechanism':{'screen_code':'RSN-04','grid':0.0001}}
def fmt(iv): return {'lo':round(float(iv[0]),6),'hi':round(float(iv[1]),6)}
for q in Q['cells']:
    c,w=lin_mean(q['cell']); iv=interval(w,c); out['cells'][q['id']]=fmt(iv); print(q['id'],len(cellruns(q['cell'])),len(w),fmt(iv))
for q in Q['contrasts']:
    c,w=combine(lin_mean(q['to']),lin_mean(q['from']),-1); iv=interval(w,c); out['contrasts'][q['id']]=fmt(iv); print(q['id'],fmt(iv))
for q in Q['decisions']:
    c,w=combine(lin_mean(q['to']),lin_mean(q['from']),-1); lo,hi=interval(w,c); m=F(str(q['margin']))
    ans='yes' if lo>m else ('no' if hi<=m else 'cannot_tell'); out['decisions'][q['id']]=ans; print(q['id'],fmt((lo,hi)),m,ans)
for q in Q['supports']:
    r=q['run_id']
    if r in V: iv=(V[r],V[r])
    else: iv=interval({r:F(1)},F(0))
    out['supports'][q['id']]=fmt(iv); print(q['id'],r,retids.get(r),plan[r]['suite'],RT[r],B.get(r),fmt(iv))
json.dump(out,open('/app/answers.json','w'),indent=1)
